create or replace function public.sync_post_likes_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (tg_op = 'INSERT') then
    update public.posts set likes_count = coalesce(likes_count, 0) + 1 where id = new.post_id;
    return new;
  elsif (tg_op = 'DELETE') then
    update public.posts set likes_count = greatest(coalesce(likes_count, 0) - 1, 0) where id = old.post_id;
    return old;
  end if;
  return null;
end;
$$

create or replace function public.award_medal(p_post_id uuid)
returns json
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_creator uuid;
  v_new integer;
begin
  if v_uid is null then
    return json_build_object('ok', false, 'error', 'auth');
  end if;

  select creator_profile_id into v_creator from public.posts where id = p_post_id;
  if v_creator is null then
    return json_build_object('ok', false, 'error', 'post');
  end if;

  insert into public.medal_balances (fan_user_id, balance)
    values (v_uid, 0)
    on conflict (fan_user_id) do nothing;

  update public.medal_balances
    set balance = balance - 1, updated_at = now()
    where fan_user_id = v_uid and balance >= 1
    returning balance into v_new;

  if v_new is null then
    return json_build_object('ok', false, 'error', 'insufficient',
      'balance', coalesce((select balance from public.medal_balances where fan_user_id = v_uid), 0));
  end if;

  insert into public.medal_awards (post_id, creator_profile_id, fan_user_id, medal_type, points, amount_usd)
    values (p_post_id, v_creator, v_uid, 'medal', 1, 0);

  return json_build_object('ok', true, 'balance', v_new);
end;
$$

create or replace function public.ensure_referral_code(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_code text;
begin
  select code into v_code from public.referral_codes where owner_user_id = p_user;
  if v_code is not null then
    return v_code;
  end if;
  loop
    v_code := lower(substr(md5(gen_random_uuid()::text), 1, 8));
    begin
      insert into public.referral_codes (owner_user_id, code) values (p_user, v_code);
      return v_code;
    exception when unique_violation then
      select code into v_code from public.referral_codes where owner_user_id = p_user;
      if v_code is not null then
        return v_code;
      end if;

    end;
  end loop;
end;
$$

create or replace function public.record_referral(p_code text, p_referred uuid, p_type text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid;
begin
  if p_code is null or p_referred is null then
    return;
  end if;
  select owner_user_id into v_owner from public.referral_codes where code = p_code;
  if v_owner is null or v_owner = p_referred then
    return;
  end if;
  insert into public.referral_signups (code, referred_user_id, referred_account_type)
    values (p_code, p_referred, coalesce(p_type, 'fan'))
    on conflict (referred_user_id) do nothing;
end;
$$

